const fs=require('fs'),path=require('path'),assert=require('assert');
const {createRequire}=require('module');
const semver=require('/opt/homebrew/lib/node_modules/npm/node_modules/semver');
const root=process.cwd(),manifest=JSON.parse(fs.readFileSync('package.json'));
const packages=[],seen=new Set();
function visit(nm){
 if(!fs.existsSync(nm))return;
 for(const name of fs.readdirSync(nm).sort()){
  if(name.startsWith('.'))continue;
  const dirs=name.startsWith('@')?fs.readdirSync(path.join(nm,name)).map(p=>name+'/'+p):[name];
  for(const p of dirs){const dir=path.join(nm,p),file=path.join(dir,'package.json');if(!fs.existsSync(file))continue;
   const info=JSON.parse(fs.readFileSync(file)),real=fs.realpathSync(dir);if(seen.has(real))continue;seen.add(real);
   const realNm=info.name?.startsWith('@')?path.dirname(path.dirname(real)):path.dirname(real);
   packages.push({dir:real,info,nm:real.startsWith(root+'/node_modules/')?realNm:nm});assert(packages.length<=10000,"bounded identity traversal");visit(path.join(real,'node_modules'));}
 }
}
function find(name,parent){
 const req=createRequire(path.join(parent,'package.json'));
 for(const lookup of req.resolve.paths(name)||[]){const file=path.join(lookup,name,'package.json');if(fs.existsSync(file))return JSON.parse(fs.readFileSync(file));}
}
function edges(info,parent){
 for(const [name,range] of Object.entries(info.dependencies||{})){
  const optional=Object.hasOwn(info.optionalDependencies||{},name),child=find(name,parent);
  if(!child&&optional)continue;
  assert(child,`missing required ${info.name||'root'} -> ${name}`);
  assert(semver.satisfies(child.version,range),`incompatible ${info.name||'root'} -> ${name} ${range}, actual ${child.version}`);
 }
 for(const [name,range] of Object.entries(info.peerDependencies||{})){
  const child=find(name,parent);if(!child&&info.peerDependenciesMeta?.[name]?.optional)continue;
  assert(child&&semver.satisfies(child.version,range),`peer mismatch ${info.name} -> ${name} ${range}`);
 }
}
(async()=>{
 visit(path.join(root,'node_modules'));assert(packages.length,'no installed identities');edges(manifest,root);
 for(const name of Object.keys(manifest.dependencies||{})){
  const p=find(name,root);assert(p?.version===manifest.dependencies[name],`root pin differs: ${name}`);
  require.resolve(name,{paths:[root]});await import(name);
 }
 let bins=0;
 for(const p of packages){edges(p.info,p.dir);
  const entries=typeof p.info.bin==='string'?{[p.info.name.split('/').pop()]:p.info.bin}:p.info.bin||{};
  for(const name of Object.keys(entries)){fs.accessSync(path.join(p.nm,'.bin',name),fs.constants.X_OK);bins++;}
 }
 console.log(JSON.stringify({status:'pass',package_count:packages.length,bins_checked:bins,inventory:packages.map(p=>({path:path.relative(root,p.dir),name:p.info.name,version:p.info.version})),quality:'exact root pins; required and peer SemVer edges; CJS resolution; ESM imports; executable bins'}));process.exit(0);
})().catch(e=>{console.error(e.stack);process.exit(1)});
